// Bundle the Mycel compiler + runtime for the browser (WO111 item 19) — no bundler dependency: tsc's CommonJS output
// in dist/src is wrapped module by module behind a tiny `require`, Node built-ins on the compile/run path get small
// shims, and std/*.olx is embedded so the resolver's `fs` reads come from memory.
// usage: node web/build.mjs [outDir]      (default ../site/public/mycel/play; run `npm run build` first)
import * as fs from "node:fs";
import * as path from "node:path";
import * as zlib from "node:zlib";

const here = path.dirname(new URL(import.meta.url).pathname);
const lang = path.resolve(here, "..");
const dist = path.join(lang, "dist", "src");
const out = path.resolve(process.argv[2] ?? path.join(lang, "..", "site", "public", "mycel", "play"));

// Modules reached from the browser entry (followed through require("./x") calls).
const mods = new Map();
const visit = (name) => {
  if (mods.has(name)) return;
  // The Java bridge (src/bridges/) needs child processes and a JVM; the playground never has either.
  if (name === "bridges") {
    mods.set(name, `const gone = (what) => () => { throw new Error(what + " is not available in the browser playground"); };\nexports.SyncJavaBridge = class { constructor() { gone("Java packages")(); } };\nexports.installMaven = gone("Java packages");\nexports.scanJarProvides = gone("Java packages");`);
    return;
  }
  const file = path.join(dist, name + ".js");
  let code = fs.readFileSync(file, "utf8").replace(/\n\/\/# sourceMappingURL=.*$/m, "");
  mods.set(name, code);
  for (const m of code.matchAll(/require\("\.\/([\w-]+)"\)/g)) visit(m[1]);
};
visit("browser");

// Every std module that runs without a capability (the playground grants none; fs/http/process/env/sqlite would
// only return CapabilityError, so they are still embedded for honest error messages).
const std = {};
for (const f of fs.readdirSync(path.join(lang, "std"))) if (/\.(olx|myc)$/.test(f)) std["/std/" + f] = fs.readFileSync(path.join(lang, "std", f), "utf8");

const shims = `
const STD = ${JSON.stringify(std)};
const notInBrowser = (what) => () => { throw new Error(what + " is not available in the browser playground"); };
const pathShim = (() => {
  const norm = (p) => { const abs = p.startsWith("/"); const out = []; for (const s of p.split("/")) { if (!s || s === ".") continue; if (s === "..") out.pop(); else out.push(s); } return (abs ? "/" : "") + out.join("/"); };
  const join = (...a) => norm(a.filter(Boolean).join("/"));
  return { sep: "/", join, resolve: (...a) => { let p = ""; for (const x of a) p = x.startsWith("/") ? x : (p ? p + "/" + x : x); return norm(p.startsWith("/") ? p : "/" + p); },
    dirname: (p) => p.replace(/\\/[^/]*$/, "") || "/", basename: (p, e) => { const b = p.replace(/^.*\\//, ""); return e && b.endsWith(e) ? b.slice(0, -e.length) : b; },
    extname: (p) => (/\\.[^./]*$/.exec(p) || [""])[0], relative: (a, b) => b, isAbsolute: (p) => p.startsWith("/"), normalize: norm };
})();
const fsShim = { existsSync: (p) => p in STD, readFileSync: (p) => { if (p in STD) return STD[p]; throw new Error("no such file: " + p); },
  statSync: notInBrowser("files"), readdirSync: () => [], realpathSync: (p) => p };
const vmShim = { Script: class { constructor(code, o) { this.code = code + "\\n//# sourceURL=" + ((o && o.filename) || "ply:bundle"); } runInThisContext() { return (0, eval)(this.code); } } };
const BUILTINS = { fs: fsShim, path: pathShim, vm: vmShim, crypto: { randomUUID: () => crypto.randomUUID(), createHash: notInBrowser("std.crypto hashing") },
  zlib: {}, url: { fileURLToPath: (u) => u, pathToFileURL: (p) => p }, http: {}, https: {}, child_process: {}, worker_threads: {}, module: { createRequire: () => notInBrowser("npm packages") }, "node:sqlite": {}, readline: {}, os: { homedir: () => "/", tmpdir: () => "/tmp" } };
if (typeof globalThis.process === "undefined") globalThis.process = { on() {}, off() {}, env: {}, platform: "browser", argv: [], cwd: () => "/" };
if (typeof globalThis.setImmediate === "undefined") globalThis.setImmediate = (f) => setTimeout(f, 0);
`;

const body = [...mods].map(([name, code]) =>
  `${JSON.stringify(name)}: function (module, exports, require, __dirname, __filename) {\n${code}\n}`).join(",\n");
const bundle = `/* Mycel ${JSON.parse(fs.readFileSync(path.join(lang, "package.json"), "utf8")).version} — compiler + runtime for the browser. Generated by lang/web/build.mjs; do not edit. */
(function (root) {
"use strict";
${shims}
const defs = {
${body}
};
const cache = {};
function load(name) {
  if (cache[name]) return cache[name].exports;
  const module = { exports: {} };
  cache[name] = module;
  defs[name](module, module.exports, (r) => r.startsWith("./") ? load(r.slice(2)) : (BUILTINS[r] ?? BUILTINS[r.replace(/^node:/, "")] ?? notInBrowser(r)()), "/dist/src", "/dist/src/" + name + ".js");
  return module.exports;
}
root.Mycel = load("browser");
})(typeof self !== "undefined" ? self : globalThis);
`;
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "mycel.js"), bundle);
// .js on the site is cached for a year (immutable): stamp the page's script/worker URLs with a content hash so a new
// build is fetched. Only when building into the site's play/ directory.
const page = path.join(out, "index.html");
if (fs.existsSync(page)) {
  const { createHash } = await import("node:crypto");
  const h = createHash("sha256");
  for (const f of ["mycel.js", "worker.js", "examples.js"]) if (fs.existsSync(path.join(out, f))) h.update(fs.readFileSync(path.join(out, f)));
  const v = h.digest("hex").slice(0, 10);
  fs.writeFileSync(page, fs.readFileSync(page, "utf8").replace(/(examples\.js|worker\.js)\?v=[0-9a-f]+/g, `$1?v=${v}`));
}
const gz = zlib.gzipSync(bundle).length;
console.log(`wrote ${path.relative(process.cwd(), path.join(out, "mycel.js"))}: ${mods.size} modules, ${(bundle.length / 1024).toFixed(0)} KB, ${(gz / 1024).toFixed(0)} KB gzip`);
